import { refresh } from 'next/cache';
import { cookies } from 'next/headers';

const NOTIFICATION_COOKIE = 'notifications-enabled';

export default async function Home() {
  const cookieStore = await cookies();
  const notificationsEnabled = cookieStore.get(NOTIFICATION_COOKIE)?.value === 'on';

  async function toggleNotificationPreference() {
    'use server';

    const actionCookieStore = await cookies();
    const isCurrentlyEnabled =
      actionCookieStore.get(NOTIFICATION_COOKIE)?.value === 'on';

    actionCookieStore.set(NOTIFICATION_COOKIE, isCurrentlyEnabled ? 'off' : 'on', {
      httpOnly: true,
      path: '/',
      sameSite: 'lax',
    });

    refresh();
  }

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently{' '}
        <strong>{notificationsEnabled ? 'ON' : 'OFF'}</strong>.
      </p>

      <form action={toggleNotificationPreference}>
        <button type="submit">
          Turn notifications {notificationsEnabled ? 'off' : 'on'}
        </button>
      </form>
    </main>
  );
}
